/* ------------------------------------------------------------------------
 * 1. CUSTOM VARIABLES  —  Dynamic (code)
 *    Under: IATF → <action> → Custom Variables → + Add → Type = Dynamic (code)
 * ------------------------------------------------------------------------ */

async ({
  fields,
  customInputFields,
  inputs,
  axios,
  extras
}) => {
  const TAG = '[customVars:generator]'

  const rows = Array.isArray(inputs?.__customInputFields__) ? inputs.__customInputFields__ : []

  const toFieldType = (dt) => {
    switch (dt) {
      case 'number':
        return 'numerical'
      case 'date':
        return 'date'
      case 'datetime':
        return 'datetime'
      case 'boolean':
        return 'boolean'
      case 'text':
      case 'email':
      case 'phone':
      case 'url':
      default:
        return 'string'
    }
  }

  const mappings = rows
    .map((row, i) => {
      const name = typeof row?.fieldName === 'string' ? row.fieldName.trim() : ''
      if (!name) {
        return null
      }
      const mapping = {
        name,
        reference: name,
        fieldType: toFieldType(row?.dataType),
      }
      return mapping
    })
    .filter(Boolean)

  return mappings
}

